409	    public static OptionCategory createAudioDelayCategory(Context context, Runnable onSetCallback) {
410	        PlayerData playerData = PlayerData.instance(context);
411	        String title = context.getString(R.string.audio_shift);
412	        String dialogTitle = context.getResources().getQuantityString(R.plurals.seconds, 10, context.getString(R.string.audio_shift));
413	
414	        List<OptionItem> items = new ArrayList<>();
415	
416	        OptionItem enableSwitch = UiOptionItem.from(context.getString(R.string.enable), item -> {
417	            if (playerData.getAudioDelayMs() != 0) {
418	                playerData.setAudioDelayEnabled(item.isSelected());
419	                onSetCallback.run();
420	            }
421	        }, playerData.isAudioDelayEnabled());
422	
423	        OptionItem audioDelay = UiOptionItem.from(title, item -> {
424	            AppDialogPresenter.instance(context).closeDialog();
425	            int delayMs = playerData.getAudioDelayMs();
426	            float delaySec = delayMs / 1_000f;
427	            SimpleEditDialog.show(
428	                    context,
429	                    dialogTitle,
430	                    Helpers.toString(delaySec),
431	                    newValue -> {
432	                        if (!Helpers.isNumeric(newValue)) {
433	                            return false;
434	                        }
435	
436	                        float newDelaySec = Helpers.parseFloat(newValue);
437	                        int newDelayMs = (int) (newDelaySec * 1_000);
438	
439	                        if (newDelayMs == delayMs) {
440	                            return false;
441	                        }
442	
443	                        if (newDelayMs == 0 && newDelaySec != 0) { // lower than 1ms
444	                            return false;
445	                        }
446	
447	                        playerData.setAudioDelayMs(newDelayMs);
448	                        playerData.setAudioDelayEnabled(newDelayMs != 0);
449	                        onSetCallback.run();
450	                        return true;
451	                    }
452	            );
453	        }, playerData.isAudioDelayEnabled());
454	
455	        items.add(enableSwitch);
456	        items.add(audioDelay);
457	
458	        return OptionCategory.from(AUDIO_DELAY_ID, OptionCategory.TYPE_CHECKBOX_LIST, title, items);
459	    }
