private static final int FILE_PICKER_REQUEST_CODE = 205;
/** Sentinel for share position: derive the position from the video's current playback position. */
private static final int SHARE_POSITION_CURRENT = -1;

/**
 * Resolves the position (in seconds) to share for a video. A {@code positionSec} of
 * {@link #SHARE_POSITION_CURRENT} means "use the video's current playback position";
 * any other value is used as-is.
 */
private static int resolveSharePositionSec(Video video, int positionSec) {
    return positionSec == SHARE_POSITION_CURRENT ? Utils.toSec(video.getPositionMs()) : positionSec;
}

/**
 * Adds share link items to existing dialog.
 */
public static void appendShareLinkDialogItem(Context context, AppDialogPresenter dialogPresenter, Video video) {
    appendShareLinkDialogItem(context, dialogPresenter, video, SHARE_POSITION_CURRENT);
}

/**
 * Adds share link items to existing dialog.
 */
public static void appendShareLinkDialogItem(Context context, AppDialogPresenter dialogPresenter, Video video, int positionSec) {
    if (video == null) {
